"""Record measured coupled-passenger evidence; only the supervisor sets status."""
import argparse,hashlib,json,sys
from pathlib import Path
from closure_support import ROOT,save
from delivery_build import OUT,NAMES,SOURCES
sys.path.insert(0,str(ROOT/'tools'))
import closure

FILES=['native/passenger_delivery.h','native/passenger_delivery.c','native/bridge/passenger_delivery_bridge.c']
def evidence(prop,level,command,result,method):
    return dict(property=prop,level=level,command=command,result=result,method=method,date='2026-11-13')
def main():
    p=argparse.ArgumentParser(description=__doc__);group=p.add_mutually_exclusive_group();group.add_argument('--draft',action='store_true');group.add_argument('--record-stop',action='store_true',help='Record the measured boundary without proposing migration');a=p.parse_args()
    cert=dict(component='passenger_delivery',status='unanalyzed',proposed_status='boundary-established',
        original=[dict(identity='GAME:'+n,address='013B:'+o,l1='c_'+n) for n,o in zip(NAMES,['15B4','15D7','16F6','172A','17E6','180A','18C8','18E6','19E0','19FB','1A42','1A7E'])],
        native=dict(files=FILES,header=FILES[0],functions=['passenger_delivery_apply','passenger_delivery_finish'],build='python verif/delivery_build.py'),
        purpose='Coupled passenger platform waiting, timed destination/question requests, exact cached-pixel approach, land/water boarding, carried fare countdown and delivery with real native item allocation and deferred completion.',
        interface=dict(inputs=['PassengerStoneSlot and immutable current/paired ActorType, separate persistent ActorRenderHistory, borrowed ten-platform geometry and two craft records.','Player count, water line, score, multiplier/cap and HUD low byte. Incoming boarding/delivery craft is separate from the stored carrier.'],
            outputs=['Ordered semantic field/index/value journal, immediate-tail request and selected craft; typed item launch and bonus sound requests.','Bonus delivery publishes score then returns a pending continuation. Only successful item allocation AND audio permit passenger_delivery_finish to update Y, cursor, countdown and HUD.'],
            effects=['Initializers seed phase, cursor FFFE, countdown 1 and phase-specific overlay/pose/request. Updating land handlers may move, display, board, or pair to water and call L1 BeginPassengerResurfacing.','Boarding publishes fare/floor, phase, carried kind, destination icon, carrier alias, hidden sprite, quick countdown 200, then frees source occupancy. Rescue reads both fares from the water descriptor before switching to its land pair.','Carried step unsigned-decrements fare above floor, signed-positive-decrements quick countdown, then may deliver immediately. Delivery clears the incoming craft, uses the stored carrier for position/fare, adds wrapping 32-bit fare*multiplier to score, and may request an item/audio before finishing.'],
            preconditions=['Ordinary disjoint accessible RAM, stack and immutable finite descriptors/animation banks. Physical actor slot below sixteen; native fields are ordinary indices, not doubled offsets.','Bridge admits DS=DGROUP, CS=GAME, even actor index below32, one of the six exact passenger descriptors and checked pair/callback identities. Land-only handlers reject water; rescue requires water; the three request/approach initializers admit both.','PlayerCount is one or two and PlayerArrayBytes is twice that value. Incoming craft is valid for boarding/rescue/delivery; active stored carrier is checked by the existing alias projection. Malformed state retains explicit L1 compatibility before native publication.','Live source is below ten with its paired doubled index for waiting/request/approach/boarding/rescue. Live destination is below ten and paired for approach/boarding/rescue/carried/delivery. Initializer destination words remain arbitrary, including wrapped icon arithmetic.','Four immutable nonempty live animation vectors terminate with FFFF inside the registered bank [Animation_0E20,1020h), at most256 live words. Due animation cursors and approach current cursors must address an available live/sentinel word; malformed vectors/cursors retain L1.','Native caller consumes each output once, applies internal tail after the journal, routes contact/audio through existing entries and bonus allocation through the actual native items bridge. Full-pool abnormal transfer does not run the continuation.']),
        callers=['DispatchActorUpdates iterates physical active slots in order; accepted itinerary placement initializes platform wait through the existing exported entry.','Land and floating request handlers call the shared initializers; floating approach calls the water-boarding entry. Water dynamics remain L1 unit six. No register/flag liveness elimination is assumed.'],
        callees=dict(native=['actor_alias_value','contact_players','passenger_delivery_finish'],bridge=['actor_bridge_alias_project','FindPlayerTouchingActor (native contact bridge)','SpawnFallingItem (native items API/bridge)','PlayAdlibEffect (existing audio entry)','BeginPassengerResurfacing (L1 unit six)','internal closed initializer/board/deliver tails']),
        indirect=dict(targets=['BeginPassengerPlatformWait','BeginPassengerDestinationDisplay','BeginPassengerQuestionDisplay','BeginPassengerApproach','BoardPassenger','DeliverPassenger','BeginPassengerResurfacing'],
            classification='Descriptor identities checked before execution; every immediate target and complete consumed journal checked at transfer. Native result requests the target; retained machine shell preserves full registers/flags/stack and original service return sites.'),
        memory=dict(owned=['Actor phase, current type pair, active pose/request/carrier alias, current sprite/overlay, X/Y, animation cursor/countdown and quick-delivery word.','Craft fare/floor/kind/icon, source platform occupancy clear, score words and HUD low byte.'],
            borrowed=['Current cached pixel X/Y and all renderer history survive; craft positions/platforms/pixel X and immutable platform geometry/icons.','Current/paired descriptor geometry, period, fare/floor/kind and animation resources. Item allocation/benefits and audio retain their existing owners.'],
            aliases='Existing per-phase table unchanged. Wait reads waiting_pose only; destination/question read request_ticks only; carried/delivery read carrier only. Approach reads none. Delivery snapshots the valid carrier before changing phase to walk; finish reads no inactive alias. ACTOR_VERIFY poisons inactive aliases.',
            renderer='No renderer histories or pixel caches are recomputed, cleared or serialized; previous coordinates, erase sprites and cached pixels remain untouched.',
            representation='Only bridge code knows original addresses, doubled identities, callback targets, stack/register/flag effects. Ordinary native code contains typed phases, resources, craft indices, arithmetic and effects.'),
        assumptions=['Actual-C proofs are one step from arbitrary admitted scalar state, rather than initialization-reachable states. Resource sizes and disjointness are explicit bounded assumptions.','L0-to-L1 remains independently rebuilt differential C/D evidence. L1-to-native proofs do not establish matching DOS bytes.','Audio is a successful observing callback in the symbolic harness; actual existing audio entries run in routine/scenario/native-host checks. The items allocator and its bridge are actual maintained C in the harness, including full pool.'],
        eliminated=['Native API has no machine registers, addresses, dispatch or flag model. An ordered typed journal retains every observable passenger/global store and the bridge validates its values/order.','Source/destination/carrier doubled byte indices are inverse-projected only under checked paired-index admission; malformed states keep L1.'],
        retained=['140-call request countdown; predecrement zero wraps to FFFF. Animation countdown/period zero wraps; frame terminal resets only on FFFF.','Wait skips busy craft to find an empty platform match; destination rejects its first busy match even when a later craft is empty; approach selects first platform match regardless of kind.','Approach equality uses stale cached pixel X plus anchor minus16 exactly, even between ticks; unequal cases animate between ticks and move only when due. No snap/overshoot tolerance.','Submersion uses the sign of the wrapped half-height+cachedY-water subtraction. First touching airborne craft triggers water pairing; water dynamics stay L1.','Fare floor comparison is unsigned across 8000. Quick countdown decrements only when signed-positive, but delivery bonus tests any nonzero quick word, including negative stale values.','Rescue publishes water fare/floor before pairing, then uses land carried kind. Delivery clears incoming DI craft but positions/scores using stored carrier, even if they differ.','Score is wrapping uint32 fare*multiplier addition. Bonus compares full unsigned multiplier/cap; actual native allocator scans twelve slots in reverse and retains negative-sprite allocation and full-pool pending transfer quirks.','Full pool preserves post-service Y/animation/HUD and performs no audio. HUD writes only its low byte after normal completion; all stale adjacent bytes/histories survive.'],
        evidence=[evidence('Evidence assembly pending','C','python verif/delivery_reproduce.py --fresh','Pending final actual-C and scratch host checks','No migration proposal before receipts are complete.')],
        amiga=dict(classification='Meaning only; DOS-specific behavior retained',finding='Accepted actor-storage/architecture model supplies names and ownership. No Amiga timing, equality, fares, layout or ordering is imported as equivalence evidence.'),
        uncertainty=['Only the supervisor promotes administrative status. Explicit malformed-state L1 fallback is compatibility, not a native proof for malformed inputs.'],
        dependencies={name:closure.actual_dependencies(ROOT/name) for name in FILES})
    cert['interface']['preconditions'].append('The fixed multiplier item resource retains its registered spawn/update/landing/expiry callback identities. Its other scalar fields remain arbitrary in B; arbitrary callback corruption of that service descriptor is outside this native proof.')
    if not a.draft:
        finite=json.loads((OUT/'evidence/enumerate_current/result.json').read_text());assert finite['result']=='PASS'
        integration=json.loads((OUT/'integration.json').read_text());assert integration['whole_status']==0 and not any(row['problems'] for row in integration['cases'])
        scenario_paths=sorted((ROOT/'tests/scenarios').glob('*.txt'))
        scenario_inputs={p.relative_to(ROOT).as_posix() for p in scenario_paths}
        assert {n for n in integration['inputs'] if n.startswith('tests/scenarios/') and n.endswith('.txt')}==scenario_inputs,'scenario set changed; rerun integration'
        for p in scenario_paths:assert integration['inputs'][p.relative_to(ROOT).as_posix()]==hashlib.sha256(p.read_bytes()).hexdigest(),'stale scenario: '+p.name
        for name in FILES:
            assert integration['build']['maintained_inputs'][name]==hashlib.sha256((ROOT/name).read_bytes()).hexdigest(),'stale integration source: '+name
        host=json.loads((OUT/'host.json').read_text());assert host['result']=='PASS' and host['check']['passed']
        assert {r['scenario'] for r in host['check']['scenarios']}=={p.stem for p in scenario_paths},'scenario set changed; rerun scratch host'
        for name in FILES:
            if name.endswith('.c'):assert host['build']['inputs'][str(ROOT/host['scratch']/name)]==hashlib.sha256((ROOT/name).read_bytes()).hexdigest(),'stale host source'
        mutants=json.loads((OUT/'mutants.json').read_text());assert all(r['result']=='DETECTED' for r in mutants)
        cases=json.loads((OUT/'cases/result.json').read_text());assert cases['result']=='PASS'
        selection=json.loads((OUT/'cases-selection-mutant/result.json').read_text());assert selection['result']=='DETECTED'
        gap=json.loads((OUT/'selection-gap/result.json').read_text());assert gap['result'] in ('EXPECTED_MISS','DETECTED_BY_BRIDGE')
        proofs=[]
        proved=[NAMES[i] for i in [0,2,4,6,8,9]] if a.record_stop else NAMES
        for name in proved:
            path=OUT/'evidence'/f'{name}_compact/result.json';proof=json.loads(path.read_text());assert proof['result']=='PASS',name
            assert '--no-array-field-sensitivity' in proof['command'] and '--arrays-uf-never' in proof['command']
            assert (path.parent/'harness.c').read_text()=='#include "pair.inc"\n'+(ROOT/'verif/delivery_harness.c').read_text(),'stale generated harness: '+name
            for source in [*FILES,*[p.relative_to(ROOT).as_posix() for p in SOURCES],
                'c/actors.c','c/actors_states.c','c/items_water.c','c/ugh.h','c/ugh_sym.h','native/actors.h',
                'verif/closure_support.py','verif/windows_job.py','metadata/verif-tools.json',
                'verif/delivery_harness.c','verif/delivery_build.py','verif/delivery_evidence.py']:
                assert proof['inputs'][source]==hashlib.sha256((ROOT/source).read_bytes()).hexdigest(),'stale proof: '+name+' '+source
            proofs.append(evidence(name+' actual-C bridged published effects','B',f'python verif/delivery_evidence.py {name} --tag compact --compact --timeout 600',f'PASS {proof["seconds"]:.3f}s with bounds/pointer/signed-overflow/unwind assertions',
                'Actual extracted L1 versus actual native core and complete bridge, real contact code and native item allocator/bridge. Arbitrary slot0..15, scalar/register/flag/history/platform/craft/item state; ten platforms, paired live indices, valid incoming/stored carriers; two live arbitrary non-FFFF frame words per vector and terminal. Due cursors FFFE/0/2; approach non-due current0/2/4; otherwise dormant cursors any word. First passenger pair, symbolic geometry/fares/period/kind; shared initializers symbolic land/water. Difficulty0 with arbitrary cap. Other two pairs/difficulties/general vector sizes remain C. No reachability or pool-availability assumption. Item-internal store order belongs to existing allocator closure; all item words, calls, full machine state and caller/global/stack store order are compared.'))
        negative=json.loads((OUT/'evidence/BeginPassengerPlatformWait_compact_negative/result.json').read_text());assert negative['result']=='FAIL' and any(r[0]=='delivery_prepare.unwind.0' for r in negative['failures'])
        cert['evidence']=[evidence('Bridged published effects on complete finite scalar slices','A','python verif/delivery_evidence.py enumerate',finite['stdout'].strip(),
            'Seven 65536-word slices: destination icon input; destination/question request counter; carried fare and quick words; cached approach X; delivery fare. Other inputs fixed. Observations are published machine state, registers/flags, calls and caller store order; this does not prove unconsumed native selected/control or all private working-slot fields. Eleven-by-eleven boundary grids and 6000x12 generated states are C, not A.'),
            *proofs,evidence('Routine bridge/device observations','C','python verif/delivery_integration.py --whole --local-reference',f'PASS {len(integration["cases"])} normal/poisoned cases',
                'Five maintained suites, actual L0 independent reference, full observations. Receipt separates native entries from explicit malformed/resource fallback; compiled finite/generated harness additionally asserts zero fallback.'),
            evidence('Whole-game observations','D','python verif/delivery_integration.py --whole --local-reference',f'PASS all {len(scenario_paths)} maintained scenarios',
                'Frame/state/device/log digests; zero passenger fallback in whole-game audit. Receipt identifies entries reached; question/rescue are not claimed reached when audit is zero.'),
            evidence('Independent carrier and resource matrices','C','python verif/delivery_cases.py',cases['stdout'].strip(),cases['domain']),
            evidence('Native selected output fixture control','C','python verif/delivery_cases.py --selection-mutant','DETECTED selected-only defect independently of retained machine DI',
                'The finite semantic fixture observes result.selected itself. The separate selection-gap diagnostic records whether the production bridge binds that value; a machine-only miss is not positive evidence.'),
            evidence('Real scratch promotion/native host','D','python verif/delivery_host.py','PASS actual tools/closure.py; tools/hostbuild.py; host/check.py --variant native',
                f'Pinned clean committed baseline with only owned files overlaid, only scratch passenger_delivery promoted; all {len(scenario_paths)} maintained scenarios and attract smoke pass.'),
            evidence('Defect and production-unwind controls','C','python verif/delivery_mutants.py; python verif/delivery_evidence.py BeginPassengerPlatformWait --tag compact --compact --negative --timeout 180',
                f'PASS {len(mutants)} defects detected; actual delivery_prepare insufficient unwind fails',
                'Private native source mutants, maintained files unchanged; bounds/unwinding assertions enabled.')]
        if a.record_stop:
            pending=[n for n in NAMES if n not in proved]
            cert['proposed_status_reason']='Recorded stop at boundary-established: implementation, finite/C/D checks and scratch host pass, but full-domain actual-C proofs for six coupled updating handlers remain open. Do not promote to migrated on the passing tests.'
            cert['recorded_stop']=dict(proved_entries=proved,pending_entries=pending,
                cause='Large whole-domain bridge formulas exceed practical solver memory/time. No reachability, scalar-boundary, full-pool or machine-observation restriction is introduced to make them pass.',
                continuation='Keep the actual-C harness and complete compared state. Optimize exact array/log/dispatch encoding or prove an equivalent composition before replaying all six open entries. Finish only after every profile and the final scratch host gate pass.',
                command='python verif/delivery_reproduce.py --fresh --record-stop --working-tree-lint')
            cert['recorded_stop']['native_projection']='The six B rows prove the actual C bridged published effects, not a standalone equivalence of every native in/out slot/world/control field. Before native closure, compare the active native working-state projection with the L1 step and enforce complete next/pending/selected request consumption. Do not infer those properties from correct journal publication.'
            if gap['result']=='EXPECTED_MISS':
                cert['proposed_status_reason']+=' The native selected-craft result must also be bound to the immediate boarding/delivery tail; its diagnostic mutation currently escapes the machine-only harness.'
                cert['recorded_stop']['selected_tail_binding']='Open: delivery_dispatch checks target and journal but does not bind result.selected to incoming craft for BOARD/DELIVER tails. A selected-only mutation passes the original 531163-case machine harness, while the new direct finite selected-output fixture detects it. Add checked native-selected DI publication and replay all affected proofs before migration.'
                cert['uncertainty'].append('Recorded selected-craft composition gap: native result.selected is not consumed by the current bridge at BOARD/DELIVER immediate tails. Current native selection matches the direct finite fixture, but the original bridge comparison cannot certify this output. See verif/delivery_selection_gap.py.')
            cert['uncertainty'].append('No B claim for '+', '.join(pending)+'. Their broad scalar/state behavior currently has A finite slices and C/D evidence only. The coupled unit remains unclosed.')
        else:
            assert gap['result']=='DETECTED_BY_BRIDGE','selected tail output is not bound; cannot propose migrated'
            cert['proposed_status']='migrated';cert['proposed_status_reason']='Finite scalar proofs, per-handler actual-C bounded proofs, C/D bridge/resource integration and actual scratch native-host promotion pass. General resource sizes and malformed compatibility remain C.'
        cert['uncertainty']+=['Early duplicated-log/general-dispatch profiles timed out at300/600s or were canceled after replacement; diagnostic receipts earn no proof. Final streaming store comparator preserves the same exact ordered caller/global/stack observations while avoiding a redundant symbolic log copy. Per-entry COMPLETE target sets and immediate-tail depth are asserted, never assumed.','Unit-six water state updates remain L1. The shared initializers and water-boarding entry are closed here; no closure claim for the water state machine.']
        cert['scratch_acceptance']=dict(baseline_revision=host['baseline_revision'],linked_components=[r['component'] for r in host['build']['linked_units']],scenarios=[r['scenario'] for r in host['check']['scenarios']],smoke=host['check']['smoke'])
        inputs=[ROOT/n for n in FILES]+SOURCES+list((ROOT/'verif').glob('delivery*'))+[ROOT/n for n in [
            'native/actors.h','native/actor_resources.h','native/contacts.h','native/items.h','native/level.h','native/geometry.h','native/bridge/actor_projection.h',
            'c/actors.c','c/actors_states.c','c/items_water.c','c/ugh.h','c/ugh_sym.h','verif/closure_support.py','verif/windows_job.py','verif/contacts_reference.py',
            'tools/closure.py','tools/nbuild.py','tools/hostbuild.py','tools/wholegame.py','tools/difftest.py','host/check.py','metadata/verif-tools.json']]
        inputs += sorted((ROOT/'tests/scenarios').glob('*.txt'))+[ROOT/'tests'/f'{s}.py' for s in ['items_water','actors_states','actors','render','scene']]
        cert['verification_input_hashing']='sha256-lf-text';cert['verification_inputs']={p.relative_to(ROOT).as_posix():hashlib.sha256(p.read_bytes().replace(b'\r\n',b'\n')).hexdigest() for p in inputs}
    save(ROOT/'metadata/closure/passenger_delivery.json',cert)
if __name__=='__main__':main()
